#!/usr/bin/env node
'use strict';

const { spawnSync } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const catalog = require('../lib/api-catalog');
const { camelToSnake } = require('../lib/api-factory');

const HEADER = [
  '/*',
  ' * Generated by scripts/generate-api-types.js.',
  ' * Sources: lib/api-catalog.js, lib/types.js, docs/api-responses-reference.json.',
  ' * Do not edit this file directly.',
  ' */',
  '',
].join('\n');

function catalogRoutes() {
  const routes = [];
  const seen = new Set();

  Object.entries(catalog).forEach(([namespace, definition]) => {
    definition.methods.forEach((method) => {
      const route = `${definition.module}.${camelToSnake(method)}`;
      if (seen.has(route)) throw new Error(`Duplicate RPC route in catalog: ${route}`);
      seen.add(route);
      routes.push({ namespace, method, route });
    });
  });
  return routes;
}

function documentedRouteTypes(source) {
  const result = { params: new Map(), responses: new Map() };
  const blocks = source.match(/\/\*\*[\s\S]*?\*\//g) || [];

  blocks.forEach((block) => {
    const marker = block.split(/\r?\n/).find((line) => (
      line.includes('Response from') || line.includes('Parameters for')
    ));
    if (!marker) return;
    const typedef = block.match(/@typedef\s+\{object\}\s+([A-Za-z][A-Za-z0-9_]*)/);
    if (!typedef) throw new Error(`Documented RPC route has no object typedef: ${marker.trim()}`);
    const routes = marker.match(/[a-z0-9][a-z0-9_-]*\.[a-z][a-z0-9_]*/g) || [];
    if (!routes.length) throw new Error(`Documented RPC type has no route: ${marker.trim()}`);
    const target = marker.includes('Response from') ? result.responses : result.params;
    routes.forEach((route) => {
      if (target.has(route)) throw new Error(`Duplicate documented RPC type: ${route}`);
      target.set(route, typedef[1]);
    });
  });

  return result;
}

function pascalCase(value) {
  return value
    .split(/[^A-Za-z0-9]+/)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join('');
}

function emitJSDocTypes(root) {
  const packageFile = require.resolve('typescript/package.json', { paths: [root] });
  const typescriptPackage = JSON.parse(fs.readFileSync(packageFile, 'utf8'));
  const tsc = path.resolve(path.dirname(packageFile), typescriptPackage.bin.tsc);
  const temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'gl-sdk4-api-types-'));

  try {
    const result = spawnSync(process.execPath, [
      tsc,
      '--allowJs',
      '--declaration',
      '--emitDeclarationOnly',
      '--module', 'commonjs',
      '--target', 'ES2020',
      '--outDir', temporary,
      path.join(root, 'lib', 'types.js'),
    ], {
      cwd: root,
      encoding: 'utf8',
      shell: false,
    });
    if (result.error || result.status !== 0) {
      throw new Error(
        result.error
          ? `Cannot run TypeScript: ${result.error.message}`
          : `TypeScript declaration emit failed: ${String(result.stderr || result.stdout).trim()}`
      );
    }
    return fs.readFileSync(path.join(temporary, 'types.d.ts'), 'utf8').replace(/\r\n/g, '\n');
  } finally {
    fs.rmSync(temporary, { recursive: true, force: true });
  }
}

function generateApiTypes(options) {
  const root = path.resolve(options && options.root || path.join(__dirname, '..'));
  const routes = catalogRoutes();
  const routeSet = new Set(routes.map(({ route }) => route));
  const typesSource = fs.readFileSync(path.join(root, 'lib', 'types.js'), 'utf8');
  const documented = documentedRouteTypes(typesSource);
  const responseFixture = JSON.parse(fs.readFileSync(
    path.join(root, 'docs', 'api-responses-reference.json'),
    'utf8'
  ));

  for (const route of [...documented.responses.keys(), ...documented.params.keys()]) {
    if (!routeSet.has(route)) {
      throw new Error(`Documented RPC route is missing from api-catalog: ${route}`);
    }
  }
  for (const route of [
    ...Object.keys(responseFixture.methods),
    ...Object.keys(responseFixture.feature_gated || {}),
  ]) {
    if (!routeSet.has(route)) {
      throw new Error(`Response fixture route is missing from api-catalog: ${route}`);
    }
  }

  const knownTypes = new Set([
    ...documented.responses.values(),
    ...documented.params.values(),
  ]);
  const observedResponses = new Map();
  routes.forEach(({ namespace, method, route }) => {
    const observation = responseFixture.methods[route];
    if (documented.responses.has(route) || !observation || observation.status !== 'ok' ||
        !Array.isArray(observation.keys) || observation.keys.length === 0) return;
    observedResponses.set(
      route,
      {
        keys: observation.keys,
        type: `${pascalCase(namespace)}${pascalCase(method)}ObservedResponse`,
      }
    );
  });

  const lines = [HEADER.trimEnd()];
  const importedTypes = [...knownTypes].sort();
  if (importedTypes.length) {
    lines.push('import type {');
    importedTypes.forEach((type) => lines.push(`  ${type},`));
    lines.push("} from './lib/types';", '');
    lines.push('export type {');
    importedTypes.forEach((type) => lines.push(`  ${type},`));
    lines.push("} from './lib/types';", '');
  }
  lines.push('export type RpcParams = Record<string, unknown>;', '');

  observedResponses.forEach(({ keys, type }, route) => {
    lines.push(`/** Object keys observed for ${route} on firmware ${responseFixture.firmware}. */`);
    lines.push(`export interface ${type} {`);
    keys.forEach((key) => lines.push(`  ${JSON.stringify(key)}?: unknown;`));
    lines.push('}', '');
  });

  Object.keys(catalog).forEach((namespace) => {
    lines.push(`export interface ${pascalCase(namespace)}Api {`);
    routes.filter((entry) => entry.namespace === namespace).forEach(({ method, route }) => {
      const paramsType = documented.params.get(route);
      const observed = observedResponses.get(route);
      const responseType = documented.responses.get(route) || (observed && observed.type) || 'unknown';
      const params = paramsType ? `params: ${paramsType}` : 'params?: RpcParams';
      lines.push(`  ${method}(${params}): Promise<${responseType}>;`);
    });
    lines.push('}', '');
  });

  lines.push('export interface GlSdk4Api {');
  Object.keys(catalog).forEach((namespace) => {
    lines.push(`  ${namespace}: ${pascalCase(namespace)}Api;`);
  });
  lines.push('}', '');

  return {
    documentedParamCount: documented.params.size,
    documentedResponseCount: documented.responses.size,
    jsdocTypes: emitJSDocTypes(root),
    methodCount: routes.length,
    namespaceCount: Object.keys(catalog).length,
    observedResponseCount: observedResponses.size,
    rpcTypes: lines.join('\n'),
  };
}

function writeGeneratedTypes(options) {
  const root = path.resolve(options && options.root || path.join(__dirname, '..'));
  const check = Boolean(options && options.check);
  const generated = generateApiTypes({ root });
  const files = [
    [path.join(root, 'rpc-api.d.ts'), generated.rpcTypes],
    [path.join(root, 'lib', 'types.d.ts'), generated.jsdocTypes],
  ];
  const stale = files.filter(([file, content]) => (
    !fs.existsSync(file) || fs.readFileSync(file, 'utf8') !== content
  ));

  if (check && stale.length) {
    throw new Error(`Generated API types are stale: ${stale.map(([file]) => path.relative(root, file)).join(', ')}`);
  }
  if (!check) files.forEach(([file, content]) => fs.writeFileSync(file, content));
  return generated;
}

if (require.main === module) {
  const args = process.argv.slice(2);
  if (args.some((arg) => arg !== '--check')) {
    console.error('Usage: node scripts/generate-api-types.js [--check]');
    process.exitCode = 2;
  } else {
    try {
      const generated = writeGeneratedTypes({ check: args.includes('--check') });
      console.log(
        `${args.includes('--check') ? 'Verified' : 'Generated'} ${generated.namespaceCount} namespaces, ` +
        `${generated.methodCount} methods, and ${generated.documentedResponseCount + generated.observedResponseCount} response types.`
      );
    } catch (error) {
      console.error(`Error: ${error.message}`);
      process.exitCode = 1;
    }
  }
}

module.exports = {
  catalogRoutes,
  documentedRouteTypes,
  generateApiTypes,
  writeGeneratedTypes,
};
